1	import { mkdir, readFile, writeFile, access, copyFile } from "node:fs/promises";
2	import { execSync } from "node:child_process";
3	
4	// JSON.stringify is used as a safe shell-arg quoter for known-shape strings
5	// like Jira branch names; treat any string passed to execSync that way.
6	
7	const mode = process.argv[2];
8	if (!mode) {
9	  throw new Error("Usage: jira-dispatch.mjs <prepare-dispatch|record-run|commit-changes|ensure-pr|comment-result>");
10	}
11	
12	const env = process.env;
13	
14	let jiraBaseUrl;
15	let jiraHeaders;
16	
17	run().catch((err) => {
18	  console.error(err);
19	  process.exit(1);
20	});
21	
22	async function run() {
23	  if (mode === "prepare-dispatch") return prepareDispatch();
24	  if (mode === "record-run") return recordRun();
25	  if (mode === "commit-changes") return commitChanges();
26	  if (mode === "ensure-pr") return ensurePr();
27	  if (mode === "comment-result") return commentResult();
28	  throw new Error(`Unknown mode: ${mode}`);
29	}
30	
31	function requireEnv(name) {
32	  const v = env[name];
33	  if (!v) throw new Error(`Missing required environment variable: ${name}`);
34	  return v;
35	}
36	
37	function initJira() {
38	  const baseUrl = requireEnv("JIRA_BASE_URL").replace(/\/+$/, "");
39	  const email = requireEnv("JIRA_EMAIL");
40	  const token = requireEnv("JIRA_API_TOKEN");
41	  jiraBaseUrl = baseUrl;
42	  jiraHeaders = {
43	    Authorization: `Basic ${Buffer.from(`${email}:${token}`).toString("base64")}`,
44	    Accept: "application/json",
45	    "Content-Type": "application/json",
46	  };
47	}
48	
49	async function fetchJson(url, options) {
50	  const response = await fetch(url, options);
51	  if (!response.ok) {
52	    const body = await response.text();
53	    throw new Error(`HTTP ${response.status} ${response.statusText} for ${url}: ${body}`);
54	  }
55	  return response.json();
56	}
57	
58	async function appendGithubEnv(values) {
59	  const file = env.GITHUB_ENV;
60	  if (!file) return;
61	  const body = Object.entries(values)
62	    .map(([k, v]) => {
63	      const s = String(v ?? "");
64	      if (s.includes("\n")) return `${k}<<EOF_${k}\n${s}\nEOF_${k}`;
65	      return `${k}=${s}`;
66	    })
67	    .join("\n");
68	  await writeFile(file, body + "\n", { flag: "a" });
69	}
70	
71	async function pathExists(p) {
72	  try {
73	    await access(p);
74	    return true;
75	  } catch {
76	    return false;
77	  }
78	}
79	
80	async function readJsonOrEmpty(p) {
81	  try {
82	    const raw = await readFile(p, "utf8");
83	    return raw.trim() ? JSON.parse(raw) : {};
84	  } catch {
85	    return {};
86	  }
87	}
88	
89	function nowIso() {
90	  return new Date().toISOString();
91	}
92	
93	function compactStamp() {
94	  return new Date().toISOString().replace(/[-:]/g, "").replace(/\..+$/, "Z");
95	}
96	
97	function lower(s) {
98	  return String(s ?? "").toLowerCase();
99	}
100	
101	function tableRow(value) {
102	  return String(value || "-").replace(/\|/g, "\\|").replace(/\n/g, "<br>");
103	}
104	
105	function normalizeIssueKey(key) {
106	  const normalized = String(key || "").trim().toUpperCase();
107	  if (!/^[A-Z][A-Z0-9]+-\d+$/.test(normalized)) {
108	    throw new Error(`Invalid Jira issue key: ${key}`);
109	  }
110	  return normalized;
111	}
112	
113	function determineKind(issue) {
114	  const labels = (issue.fields?.labels ?? []).map(lower);
115	  if (labels.includes("claude:answer")) return "answer";
116	  if (labels.includes("claude:pr")) return "pr";
117	  const type = lower(issue.fields?.issuetype?.name);
118	  if (type === "question") return "answer";
119	  return "pr";
120	}
121	
122	async function prepareDispatch() {
123	  initJira();
124	  const key = normalizeIssueKey(requireEnv("ISSUE_KEY"));
125	
126	  const issue = await fetchJson(
127	    `${jiraBaseUrl}/rest/api/3/issue/${encodeURIComponent(key)}?fields=summary,description,status,assignee,reporter,priority,issuetype,labels,components,created,updated,comment&expand=renderedFields`,
128	    { headers: jiraHeaders },
129	  );
130	
131	  const fields = issue.fields ?? {};
132	  const summary = fields.summary || key;
133	  const kind = determineKind(issue);
134	  const branchName = `tdf/${key.toLowerCase()}`;
135	
136	  // For PR mode, switch to the existing PR branch if one exists on origin so
137	  // that prior state.json, plan.md, transcript.md, and any code changes are
138	  // visible to this run. Done before any file writes to avoid untracked-file
139	  // collisions with `git checkout`.
140	  if (kind === "pr") {
141	    let branchExists = false;
142	    try {
143	      execSync(`git ls-remote --exit-code --heads origin ${JSON.stringify(branchName)}`, { stdio: "ignore" });
144	      branchExists = true;
145	    } catch {
146	      branchExists = false;
147	    }
148	    if (branchExists) {
149	      console.log(`Existing branch ${branchName} found on origin; checking out.`);
150	      execSync(`git fetch origin ${JSON.stringify(branchName)}`, { stdio: "inherit" });
151	      execSync(`git checkout -B ${JSON.stringify(branchName)} origin/${branchName}`, { stdio: "inherit" });
152	    } else {
153	      console.log(`No existing branch ${branchName}; will create from main on commit.`);
154	    }
155	  }
156	
157	  const ticketFolder = `spec/${key}`;
158	  const stateFile = `${ticketFolder}/state.json`;
159	  const transcriptFile = `${ticketFolder}/transcript.md`;
160	  const specFile = `${ticketFolder}/spec.md`;
161	  const planFile = `${ticketFolder}/plan.md`;
162	  const responseFile = `${ticketFolder}/response.md`;
163	  const runDir = `${ticketFolder}/runs/${compactStamp()}-${env.GITHUB_RUN_ID || "local"}`;
164	  const promptFile = `${runDir}/prompt.md`;
165	
166	  await mkdir(runDir, { recursive: true });
167	
168	  let isNew = true;
169	  let lastSessionId = "";
170	  if (await pathExists(stateFile)) {
171	    isNew = false;
172	    const state = await readJsonOrEmpty(stateFile);
173	    lastSessionId = state.last_session_id || "";
174	  } else {
175	    await writeFile(
176	      stateFile,
177	      JSON.stringify({ ticket_id: key, run_count: 0, kind, branch: branchName }, null, 2) + "\n",
178	      "utf8",
179	    );
180	  }
181	
182	  if (!(await pathExists(transcriptFile))) {
183	    await writeFile(transcriptFile, `# ${key} Transcript\n`, "utf8");
184	  }
185	
186	  const comments = issue.fields?.comment?.comments ?? [];
187	  await writeFile(specFile, buildSpec({ issue, comments, key }), "utf8");
188	
189	  const prompt = buildPrompt({
190	    key,
191	    summary,
192	    ticketFolder,
193	    kind,
194	    isNew,
195	    specFile,
196	    planFile,
197	    responseFile,
198	    transcriptFile,
199	  });
200	  await writeFile(promptFile, prompt, "utf8");
201	
202	  let claudeArgs = "--max-turns 60 --permission-mode bypassPermissions";
203	  if (lastSessionId) claudeArgs += ` --resume ${lastSessionId}`;
204	
205	  await mkdir(`${requireEnv("HOME")}/.claude/projects`, { recursive: true });
206	
207	  await appendGithubEnv({
208	    SHOULD_RUN: "true",
209	    ISSUE_KEY: key,
210	    ISSUE_TITLE: summary,
211	    JIRA_ISSUE_URL: `${jiraBaseUrl}/browse/${key}`,
212	    KIND: kind,
213	    BRANCH_NAME: branchName,
214	    IS_NEW: isNew ? "true" : "false",
215	    LAST_SESSION_ID: lastSessionId,
216	    TICKET_FOLDER: ticketFolder,
217	    STATE_FILE: stateFile,
218	    TRANSCRIPT_FILE: transcriptFile,
219	    SPEC_FILE: specFile,
220	    PLAN_FILE: planFile,
221	    RESPONSE_FILE: responseFile,
222	    RUN_DIR: runDir,
223	    PROMPT_FILE: promptFile,
224	    CLAUDE_ARGS: claudeArgs,
225	  });
226	
227	  console.log(`Prepared dispatch for ${key} (kind=${kind} new=${isNew} last_session=${lastSessionId || "<none>"})`);
228	}
229	
230	async function recordRun() {
231	  const stateFile = requireEnv("STATE_FILE");
232	  const transcriptFile = requireEnv("TRANSCRIPT_FILE");
233	  const responseFile = env.RESPONSE_FILE || "";
234	  const promptFile = env.PROMPT_FILE || "";
235	  const runDir = env.RUN_DIR || "";
236	  const isNew = env.IS_NEW === "true";
237	  const kind = env.KIND || "pr";
238	  const conclusion = env.CONCLUSION || "unknown";
239	  const lastSessionId = env.LAST_SESSION_ID || "";
240	  const actionSessionId = env.ACTION_SESSION_ID || "";
241	  const executionFile = env.EXECUTION_FILE || "";
242	
243	  let newSessionId = actionSessionId;
244	  let assistantText = "";
245	
246	  if (executionFile && (await pathExists(executionFile))) {
247	    try {
248	      const raw = await readFile(executionFile, "utf8");
249	      const entries = parseExecutionFile(raw);
250	      if (!newSessionId) {
251	        for (const e of entries) {
252	          if (e?.session_id) newSessionId = e.session_id;
253	        }
254	      }
255	      for (const e of entries) {
256	        if (e?.type === "assistant") {
257	          for (const part of e?.message?.content ?? []) {
258	            if (part?.type === "text" && typeof part.text === "string") {
259	              assistantText = part.text;
260	            }
261	          }
262	        }
263	      }
264	      if (runDir) {
265	        await mkdir(runDir, { recursive: true });
266	        await copyFile(executionFile, `${runDir}/execution.json`);
267	      }
268	    } catch (err) {
269	      console.warn(`Failed to parse execution_file: ${err.message}`);
270	    }
271	  }
272	
273	  if (runDir) {
274	    if (responseFile && (await pathExists(responseFile))) {
275	      await copyFile(responseFile, `${runDir}/response.md`);
276	    }
277	    if (promptFile && (await pathExists(promptFile))) {
278	      await copyFile(promptFile, `${runDir}/prompt.md`);
279	    }
280	  }
281	
282	  const now = nowIso();
283	  const rotated = lastSessionId && newSessionId && lastSessionId !== newSessionId;
284	
285	  const state = await readJsonOrEmpty(stateFile);
286	  state.ticket_id = state.ticket_id || env.ISSUE_KEY || "";
287	  state.last_session_id = newSessionId || "";
288	  state.prev_session_id = lastSessionId || null;
289	  state.last_run_at = now;
290	  state.last_conclusion = conclusion;
291	  state.last_kind = kind;
292	  state.run_count = (state.run_count || 0) + 1;
293	  if (env.BRANCH_NAME) state.branch = env.BRANCH_NAME;
294	  state.kind = kind;
295	  await writeFile(stateFile, JSON.stringify(state, null, 2) + "\n", "utf8");
296	
297	  const summarySnippet = (assistantText || "").trim().split("\n").slice(0, 12).join("\n  ");
298	  const block = [
299	    "",
300	    `## Run ${now}`,
301	    `- run_kind: ${isNew ? "new" : "continuation"}`,
302	    `- prev_session_id: ${lastSessionId || "<none>"}`,
303	    `- new_session_id: ${newSessionId || "<none>"}`,
304	    `- session_id_rotated: ${rotated ? "true" : "false"}`,
305	    `- conclusion: ${conclusion}`,
306	    `- run_dir: ${runDir || "<none>"}`,
307	    `- assistant_summary:\n  ${summarySnippet || "<empty>"}`,
308	    "",
309	  ].join("\n");
310	  await writeFile(transcriptFile, block, { flag: "a" });
311	
312	  await appendGithubEnv({ NEW_SESSION_ID: newSessionId });
313	  console.log(`Recorded run for ${env.ISSUE_KEY}: session=${newSessionId || "<none>"}`);
314	}
315	
316	function parseExecutionFile(raw) {
317	  const trimmed = raw.trim();
318	  if (!trimmed) return [];
319	  if (trimmed.startsWith("[")) {
320	    try {
321	      const arr = JSON.parse(trimmed);
322	      return Array.isArray(arr) ? arr : [];
323	    } catch {
324	      // fall through to NDJSON
325	    }
326	  }
327	  return trimmed
328	    .split("\n")
329	    .filter(Boolean)
330	    .map((line) => {
331	      try {
332	        return JSON.parse(line);
333	      } catch {
334	        return null;
335	      }
336	    })
337	    .filter(Boolean);
338	}
339	
340	function commitChanges() {
341	  const kind = env.KIND || "pr";
342	  const branchName = requireEnv("BRANCH_NAME");
343	  const issueKey = requireEnv("ISSUE_KEY");
344	  const ticketFolder = requireEnv("TICKET_FOLDER");
345	  const runId = env.GITHUB_RUN_ID || "";
346	
347	  sh("rm -f output.txt");
348	  sh('git config user.name "github-actions[bot]"');
349	  sh('git config user.email "41898282+github-actions[bot]@users.noreply.github.com"');
350	
351	  if (kind === "pr") {
352	    sh(`git checkout -B "${branchName}"`);
353	    sh("git add -A");
354	    if (gitNothingStaged()) {
355	      console.log("No changes to commit on PR branch");
356	      return appendGithubEnv({ COMMITTED: "false" });
357	    }
358	    sh(`git commit -m "${issueKey}: claude-code update (run ${runId})"`);
359	    sh(`git push origin "HEAD:${branchName}"`);
360	    return appendGithubEnv({ COMMITTED: "true" });
361	  }
362	
363	  sh(`git add -A "${ticketFolder}"`);
364	  if (gitNothingStaged()) {
365	    console.log("No artefact changes to commit on main");
366	    return appendGithubEnv({ COMMITTED: "false" });
367	  }
368	  sh(`git commit -m "${issueKey}: update ticket artefacts (run ${runId})"`);
369	  sh("git push origin HEAD:main");
370	  return appendGithubEnv({ COMMITTED: "true" });
371	}
372	
373	function gitNothingStaged() {
374	  try {
375	    execSync("git diff --cached --quiet", { stdio: "ignore" });
376	    return true;
377	  } catch {
378	    return false;
379	  }
380	}
381	
382	function sh(cmd) {
383	  execSync(cmd, { stdio: ["ignore", "inherit", "inherit"] });
384	}
385	
386	async function ensurePr() {
387	  if ((env.KIND || "pr") !== "pr") {
388	    console.log("Not PR mode, skipping ensure-pr");
389	    return;
390	  }
391	  if (env.COMMITTED !== "true") {
392	    console.log("No commit happened on this run; skipping PR.");
393	    return;
394	  }
395	
396	  const issueKey = requireEnv("ISSUE_KEY");
397	  const issueTitle = env.ISSUE_TITLE || issueKey;
398	  const branchName = requireEnv("BRANCH_NAME");
399	  const repo = requireEnv("GITHUB_REPOSITORY");
400	  const repoOwner = repo.split("/")[0];
401	  const ghToken = requireEnv("GH_TOKEN");
402	
403	  const headers = {
404	    Accept: "application/vnd.github+json",
405	    Authorization: `Bearer ${ghToken}`,
406	    "X-GitHub-Api-Version": "2022-11-28",
407	    "User-Agent": "tdf-dispatch",
408	  };
409	
410	  const listUrl = `https://api.github.com/repos/${repo}/pulls?state=open&base=main&head=${repoOwner}:${branchName}`;
411	  const existing = await fetchJson(listUrl, { headers });
412	  let prUrl = (Array.isArray(existing) && existing[0] && existing[0].html_url) || "";
413	
414	  if (!prUrl) {
415	    const body = [
416	      `Automated Claude Code update for ${issueKey}.`,
417	      "",
418	      `Jira: ${env.JIRA_ISSUE_URL || ""}`,
419	      `Ticket folder: \`${env.TICKET_FOLDER || ""}\``,
420	      "",
421	      "Review and merge when ready.",
422	    ].join("\n");
423	
424	    const created = await fetchJson(`https://api.github.com/repos/${repo}/pulls`, {
425	      method: "POST",
426	      headers: { ...headers, "Content-Type": "application/json" },
427	      body: JSON.stringify({
428	        title: `${issueKey}: ${issueTitle}`,
429	        head: branchName,
430	        base: "main",
431	        body,
432	      }),
433	    });
434	    prUrl = created.html_url;
435	  }
436	
437	  await appendGithubEnv({ PR_URL: prUrl });
438	  console.log(`Pull request: ${prUrl}`);
439	}
440	
441	async function commentResult() {
442	  initJira();
443	  const issueKey = requireEnv("ISSUE_KEY");
444	  const kind = env.KIND || "pr";
445	  const branchName = env.BRANCH_NAME || "";
446	  const responseFile = env.RESPONSE_FILE || "";
447	  const stateFile = env.STATE_FILE || "";
448	  const repo = env.GITHUB_REPOSITORY || "";
449	  const prUrl = env.PR_URL || "";
450	  let conclusion = env.CONCLUSION || "";
451	  if (!conclusion && stateFile) {
452	    const state = await readJsonOrEmpty(stateFile);
453	    conclusion = state.last_conclusion || "unknown";
454	  }
455	  if (!conclusion) conclusion = "unknown";
456	
457	  const content = [];
458	
459	  if (kind === "pr") {
460	    content.push(paragraph(`[TDF-bot] Claude Code processed ${issueKey} (conclusion: ${conclusion}).`));
461	    if (branchName && repo) {
462	      content.push(linkParagraph("Branch", `https://github.com/${repo}/tree/${encodeURIComponent(branchName)}`));
463	    }
464	    if (prUrl) content.push(linkParagraph("Pull request", prUrl));
465	    if (env.COMMITTED === "false") {
466	      content.push(paragraph("No repository changes were committed on this run."));
467	    }
468	    if (responseFile && (await pathExists(responseFile))) {
469	      const text = (await readFile(responseFile, "utf8")).trim();
470	      if (text) content.push(...markdownToAdfBlocks(text));
471	    }
472	  } else {
473	    content.push(paragraph(`[TDF-bot] Claude Code answer for ${issueKey} (conclusion: ${conclusion}):`));
474	    if (responseFile && (await pathExists(responseFile))) {
475	      const text = (await readFile(responseFile, "utf8")).trim();
476	      if (text) content.push(...markdownToAdfBlocks(text));
477	      else content.push(paragraph("_Empty response._"));
478	    } else {
479	      content.push(paragraph("_No response file produced._"));
480	    }
481	  }
482	
483	  await fetchJson(`${jiraBaseUrl}/rest/api/3/issue/${encodeURIComponent(issueKey)}/comment`, {
484	    method: "POST",
485	    headers: jiraHeaders,
486	    body: JSON.stringify({ body: { type: "doc", version: 1, content } }),
487	  });
488	  console.log(`Posted comment to ${issueKey}`);
489	}
490	
491	function paragraph(text) {
492	  return { type: "paragraph", content: [{ type: "text", text }] };
493	}
494	
495	function linkParagraph(label, href) {
496	  return {
497	    type: "paragraph",
498	    content: [
499	      { type: "text", text: `${label}: ` },
500	      { type: "text", text: href, marks: [{ type: "link", attrs: { href } }] },
501	    ],
502	  };
503	}
504	
505	function markdownToAdfBlocks(text) {
506	  const blocks = String(text)
507	    .slice(0, 30000)
508	    .split(/\n{2,}/)
509	    .map((s) => s.trim())
510	    .filter(Boolean);
511	  return blocks.map((block) => {
512	    const lines = block.split("\n");
513	    return {
514	      type: "paragraph",
515	      content: lines.flatMap((line, i) => [
516	        ...(i === 0 ? [] : [{ type: "hardBreak" }]),
517	        { type: "text", text: line },
518	      ]),
519	    };
520	  });
521	}
522	
523	function buildSpec({ issue, comments, key }) {
524	  const fields = issue.fields ?? {};
525	  const description = adfToMarkdown(fields.description).trim() || "_No description provided._";
526	  const renderedComments = (comments ?? []).map((c) => {
527	    const author = c.author?.displayName || "<unknown>";
528	    const created = c.created || "";
529	    const body = adfToMarkdown(c.body).trim() || "_<empty>_";
530	    return `### ${author} on ${created}\n\n${body}`;
531	  });
532	  return [
533	    `# ${key}: ${fields.summary ?? "Untitled Jira issue"}`,
534	    "",
535	    `Generated from Jira on ${nowIso()}.`,
536	    "",
537	    "## Issue Details",
538	    "",
539	    "| Field | Value |",
540	    "|---|---|",
541	    `| Key | ${tableRow(key)} |`,
542	    `| Title | ${tableRow(fields.summary)} |`,
543	    `| Type | ${tableRow(fields.issuetype?.name)} |`,
544	    `| Status | ${tableRow(fields.status?.name)} |`,
545	    `| Priority | ${tableRow(fields.priority?.name)} |`,
546	    `| Assignee | ${tableRow(fields.assignee?.displayName)} |`,
547	    `| Reporter | ${tableRow(fields.reporter?.displayName)} |`,
548	    `| Labels | ${tableRow((fields.labels ?? []).join(", "))} |`,
549	    `| Components | ${tableRow((fields.components ?? []).map((c) => c.name).join(", "))} |`,
550	    `| Created | ${tableRow(fields.created)} |`,
551	    `| Updated | ${tableRow(fields.updated)} |`,
552	    "",
553	    "## Description",
554	    "",
555	    description,
556	    "",
557	    `## Comments (${(comments ?? []).length})`,
558	    "",
559	    renderedComments.length ? renderedComments.join("\n\n") : "_No comments._",
560	    "",
561	  ].join("\n");
562	}
563	
564	function buildPrompt({ key, summary, ticketFolder, kind, isNew, specFile, planFile, responseFile, transcriptFile }) {
565	  const goal =
566	    kind === "pr"
567	      ? [
568	          "- Make the smallest correct repository changes to satisfy the ticket.",
569	          `- Update \`${planFile}\` with the implementation plan.`,
570	          `- Write a concise Jira-facing summary to \`${responseFile}\` (what changed, why, risks). Do not include logs or secrets.`,
571	          "- Do not create or merge pull requests; the workflow does that.",
572	        ].join("\n")
573	      : [
574	          `- Do not edit any file outside \`${ticketFolder}\`.`,
575	          `- Update \`${planFile}\` with reasoning if it helps.`,
576	          `- Write the complete answer to \`${responseFile}\` in markdown that renders correctly in Jira.`,
577	        ].join("\n");
578	
579	  const continuationNote = isNew
580	    ? ""
581	    : `- This is a continuation. If your in-memory session is missing, rebuild context from \`${transcriptFile}\`, \`${planFile}\`, and the \`runs/\` folder under the ticket.\n`;
582	
583	  return [
584	    `You are running inside \`${env.GITHUB_REPOSITORY}\` for Jira ticket \`${key}: ${summary}\`.`,
585	    "",
586	    "Read `CLAUDE.md` for repository conventions before touching files.",
587	    "",
588	    `Ticket folder: \`${ticketFolder}\`.`,
589	    `- \`${specFile}\`: a fresh snapshot of the Jira ticket and its comments. Read it. Do not edit it.`,
590	    `- \`${planFile}\`: implementation plan. You own this file. Update it as you go.`,
591	    `- \`${transcriptFile}\`: rolling history of prior runs. Read it for context if needed.`,
592	    `- \`${responseFile}\`: the message that will be posted back to Jira. You own this file.`,
593	    "",
594	    `Run kind: \`${kind}\` (${kind === "pr" ? "expects code/config changes plus a PR" : "answer-only, no code changes outside the ticket folder"}).`,
595	    `Run mode: \`${isNew ? "NEW" : "CONTINUATION"}\`.`,
596	    "",
597	    "Goal:",
598	    goal,
599	    "",
600	    "Constraints:",
601	    "- Never expose, print, or commit secrets.",
602	    "- Do not switch branches.",
603	    "- Keep tool usage minimal.",
604	    continuationNote,
605	  ].join("\n");
606	}
607	
608	function adfToMarkdown(node) {
609	  if (!node) return "";
610	  if (Array.isArray(node)) return node.map(adfToMarkdown).join("");
611	
612	  switch (node.type) {
613	    case "doc":
614	      return blockContent(node).join("\n\n");
615	    case "paragraph":
616	      return inlineContent(node);
617	    case "heading":
618	      return `${"#".repeat(node.attrs?.level ?? 2)} ${inlineContent(node)}`;
619	    case "bulletList":
620	      return listContent(node, "-");
621	    case "orderedList":
622	      return orderedListContent(node);
623	    case "listItem":
624	      return blockContent(node).join("\n");
625	    case "blockquote":
626	      return blockContent(node)
627	        .join("\n")
628	        .split("\n")
629	        .map((line) => `> ${line}`)
630	        .join("\n");
631	    case "codeBlock":
632	      return `\`\`\`\n${textContent(node)}\n\`\`\``;
633	    case "rule":
634	      return "---";
635	    case "hardBreak":
636	      return "\n";
637	    case "text":
638	      return applyMarks(node.text ?? "", node.marks ?? []);
639	    default:
640	      return blockContent(node).join("\n");
641	  }
642	}
643	
644	function blockContent(node) {
645	  return (node.content ?? []).map(adfToMarkdown).filter(Boolean);
646	}
647	
648	function inlineContent(node) {
649	  return (node.content ?? []).map(adfToMarkdown).join("");
650	}
651	
652	function listContent(node, marker) {
653	  return (node.content ?? [])
654	    .map((item) =>
655	      adfToMarkdown(item)
656	        .split("\n")
657	        .map((line, idx) => (idx === 0 ? `${marker} ${line}` : `  ${line}`))
658	        .join("\n"),
659	    )
660	    .join("\n");
661	}
662	
663	function orderedListContent(node) {
664	  const start = node.attrs?.order ?? 1;
665	  return (node.content ?? [])
666	    .map((item, idx) =>
667	      adfToMarkdown(item)
668	        .split("\n")
669	        .map((line, lineIdx) => (lineIdx === 0 ? `${start + idx}. ${line}` : `   ${line}`))
670	        .join("\n"),
671	    )
672	    .join("\n");
673	}
674	
675	function textContent(node) {
676	  if (node.type === "text") return node.text ?? "";
677	  return (node.content ?? []).map(textContent).join("");
678	}
679	
680	function applyMarks(text, marks) {
681	  return marks.reduce((value, mark) => {
682	    switch (mark.type) {
683	      case "strong":
684	        return `**${value}**`;
685	      case "em":
686	        return `_${value}_`;
687	      case "code":
688	        return `\`${value}\``;
689	      case "link":
690	        return `[${value}](${mark.attrs?.href ?? value})`;
691	      default:
692	        return value;
693	    }
694	  }, text);
695	}
